// READ ONLY. Develop merge #1098 diff + open/merged PRs on develop.
const R = 'https://api.github.com/repos/QR-CODE-App/aichecker-frontend';
return [
 { json: { tag: 'commit', url: R + '/commits/593a505462dc0352c3dc7be8759218cbb9ce1f8c?per_page=300' } },
 { json: { tag: 'commits', url: R + '/commits?sha=develop&since=2026-10-05T00:00:00Z&per_page=100' } }
];

const out = [];
const cfg = $('Config').all();
$input.all().forEach((it, i) => {
  const b = it.json.body; const tag = (cfg[i] || {json:{}}).json.tag;
  if (tag === 'search') { out.push({ tag, status: it.json.statusCode, items: ((b || {}).items || []).map(x => ({ n: x.number, t: x.title, st: x.state, pr: !!x.pull_request, url: x.html_url, upd: x.updated_at })) }); return; }
  if (tag === 'commits') { out.push({ tag, status: it.json.statusCode, items: (Array.isArray(b) ? b : []).map(c => ({ sha: c.sha, msg: ((c.commit||{}).message||'').slice(0,200), date: ((c.commit||{}).author||{}).date })), err: Array.isArray(b) ? '' : JSON.stringify(b).slice(0,300) }); return; }
  if (b && b.sha) { out.push({ tag: 'commit', sha: b.sha, msg: (b.commit||{}).message, files: (b.files||[]).map(f => ({ f: f.filename, s: f.status, p: f.patch || '' })) }); return; }
  if (Array.isArray(b)) { out.push({ tag: tag || 'list', files: b.map(f => ({ f: f.filename, s: f.status, p: f.patch || '' })) }); return; }
  out.push({ tag, status: it.json.statusCode, err: JSON.stringify(b).slice(0, 300) });
});
return [{ json: { out } }];
